'use strict';
const api='../api/index.php';const $=id=>document.getElementById(id);let stream=null,scanMode='checkin',idleTimer,finishTimer,finishSeconds=60,currentRequestKey='';
const panels=['homePanel','scanPanel','walkinPanel','ticketPanel'];
function thaiClock(){const now=new Date();$('clockTime').textContent=new Intl.DateTimeFormat('th-TH',{timeZone:'Asia/Bangkok',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(now)+' น.';$('clockDate').textContent=new Intl.DateTimeFormat('th-TH-u-ca-buddhist',{timeZone:'Asia/Bangkok',weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(now)}
thaiClock();setInterval(thaiClock,30000);
function resetIdle(){clearTimeout(idleTimer);if(!$('homePanel').classList.contains('hidden'))return;idleTimer=setTimeout(()=>show('homePanel'),90000)}
['pointerdown','keydown'].forEach(name=>document.addEventListener(name,resetIdle,{passive:true}));
function clearPrivateData(){$('scanToken').value='';$('walkinName').value='';$('walkinPhone').value='';$('scanError').classList.add('hidden');$('walkinError').classList.add('hidden');currentRequestKey='';clearInterval(finishTimer)}
function show(id){panels.forEach(x=>$(x).classList.toggle('hidden',x!==id));if(id!=='scanPanel')stopCamera();if(id==='homePanel')clearPrivateData();if(id==='walkinPanel')loadSlots();resetIdle()}
function configureScan(mode){scanMode=mode;const status=mode==='status';$('scanEyebrow').textContent=status?'QUEUE STATUS':'ONLINE CHECK-IN';$('scanTitle').textContent=status?'ตรวจสอบสถานะคิว':'เช็กอินรายการจอง';$('scanSubtitle').textContent=status?'สแกน QR จากใบคิวหรือ K-QOnline เพื่อดูสถานะ':'นำ QR จาก K-QOnline มาสแกนที่ช่องด้านล่าง';$('scanSubmit').textContent=status?'ดูสถานะคิว':'ยืนยันเช็กอิน';$('scanSubmit').value=mode}
document.querySelectorAll('[data-open]').forEach(button=>button.onclick=()=>{if(button.dataset.mode)configureScan(button.dataset.mode);show(button.dataset.open)});
document.querySelectorAll('[data-home]').forEach(button=>button.onclick=()=>show('homePanel'));$('brandHome').onclick=()=>show('homePanel');$('finishButton').onclick=()=>show('homePanel');$('printButton').onclick=()=>window.print();
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),2800)}
$('helpButton').onclick=()=>toast('ส่งสัญญาณเรียกเจ้าหน้าที่แล้ว กรุณารอสักครู่');$('accessibilityButton').onclick=()=>{document.body.classList.toggle('large-text');toast(document.body.classList.contains('large-text')?'เปิดตัวอักษรขนาดใหญ่แล้ว':'กลับเป็นตัวอักษรขนาดปกติแล้ว')};
document.querySelectorAll('[data-key]').forEach(button=>button.onclick=()=>{const key=button.dataset.key;if(key==='clear')$('scanToken').value='';else if(key==='back')$('scanToken').value=$('scanToken').value.slice(0,-1);else $('scanToken').value+=key;$('scanToken').focus()});
function tokenFrom(value){const raw=value.trim();try{const url=new URL(raw);return url.searchParams.get('t')||url.pathname.split('/').filter(Boolean).pop()||raw}catch{return raw}}
async function request(action,payload){const response=await fetch(`${api}?action=${action}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const body=await response.json();if(!response.ok)throw new Error(body.error||'ไม่สามารถดำเนินการได้');return body}
function setBusy(button,busy,label){button.disabled=busy;if(!button.dataset.label)button.dataset.label=button.textContent;button.textContent=busy?'กำลังดำเนินการ…':(label||button.dataset.label)}
$('scanForm').onsubmit=async event=>{event.preventDefault();const token=tokenFrom($('scanToken').value);$('scanError').classList.add('hidden');if(scanMode==='status'){location.href=`status.html?t=${encodeURIComponent(token)}`;return}setBusy($('scanSubmit'),true);try{const body=await request('kiosk-check-in',{token});renderTicket(body.ticket.public_id,body.ticket.queue_no,body.ticket.estimated_wait_minutes)}catch(error){$('scanError').textContent=error.message;$('scanError').classList.remove('hidden')}finally{setBusy($('scanSubmit'),false,'ยืนยันเช็กอิน')}};
function todayIso(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Bangkok',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());const get=type=>parts.find(x=>x.type===type).value;return `${get('year')}-${get('month')}-${get('day')}`}
async function loadSlots(){$('slotCards').innerHTML='<div class="loading-card">กำลังตรวจสอบบริการที่เปิดรับ…</div>';$('slotSelect').value='';try{const response=await fetch(`${api}?action=public-slots&date=${todayIso()}`,{cache:'no-store'});const body=await response.json();if(!response.ok)throw new Error(body.error);if(!body.data.length){$('slotCards').innerHTML='<div class="loading-card">ขณะนี้ยังไม่มีบริการที่เปิดรับ Walk-in<br>กรุณาติดต่อเจ้าหน้าที่</div>';return}$('slotCards').innerHTML=body.data.map(x=>`<button type="button" class="slot-card" data-slot="${x.id}"><span>${x.start_time.slice(0,5)}–${x.end_time.slice(0,5)} น.</span><strong>${escapeHtml(x.department_name)}</strong><small>${escapeHtml(x.service_name||'บริการทั่วไป')} · ${escapeHtml(x.branch_name)}</small><em><span>คิวว่าง</span><b>${Math.max(0,+x.capacity-+x.booked_count)} คิว</b></em></button>`).join('');document.querySelectorAll('.slot-card').forEach(card=>card.onclick=()=>{document.querySelectorAll('.slot-card').forEach(x=>x.classList.remove('selected'));card.classList.add('selected');$('slotSelect').value=card.dataset.slot})}catch(error){$('slotCards').innerHTML=`<div class="loading-card">${escapeHtml(error.message)}</div>`}}
function escapeHtml(value){const node=document.createElement('span');node.textContent=value??'';return node.innerHTML}
$('walkinForm').onsubmit=async event=>{event.preventDefault();$('walkinError').classList.add('hidden');if(!$('slotSelect').value){$('walkinError').textContent='กรุณาเลือกบริการที่ต้องการ';$('walkinError').classList.remove('hidden');return}if(!currentRequestKey)currentRequestKey=crypto.randomUUID?.()||`${Date.now()}-${Math.random()}`;setBusy($('walkinSubmit'),true);try{const body=await request('kiosk-walk-in',{slot_id:+$('slotSelect').value,customer_name:$('walkinName').value,customer_phone:$('walkinPhone').value,idempotency_key:currentRequestKey});renderTicket(body.ticket.public_id,body.ticket.queue_no,body.ticket.estimated_wait_minutes)}catch(error){$('walkinError').textContent=error.message;$('walkinError').classList.remove('hidden')}finally{setBusy($('walkinSubmit'),false,'ยืนยันและรับบัตรคิว')}};
function renderTicket(token,no,wait){$('ticketNo').textContent=no;$('ticketWait').textContent=wait>0?`เวลารอประมาณ ${wait} นาที`:'ใกล้ถึงคิวของคุณแล้ว';const url=new URL('status.html',location.href);url.searchParams.set('t',token);$('statusLink').href=url.href;$('ticketToken').textContent=token;const qr=qrcode(0,'M');qr.addData(url.href);qr.make();$('ticketQr').src=qr.createDataURL(7,10);show('ticketPanel');finishSeconds=60;$('finishCountdown').textContent=finishSeconds;finishTimer=setInterval(()=>{finishSeconds--;$('finishCountdown').textContent=finishSeconds;if(finishSeconds<=0)show('homePanel')},1000)}
async function stopCamera(){if(stream){stream.getTracks().forEach(track=>track.stop());stream=null}$('video').classList.add('hidden');$('cameraIdle').classList.remove('hidden')}
function handleScanned(value){$('scanToken').value=tokenFrom(value);stopCamera();$('scanForm').requestSubmit()}
$('cameraButton').onclick=async()=>{if(!('BarcodeDetector'in window)){$('scanError').textContent='อุปกรณ์นี้ยังไม่รองรับกล้องสแกนอัตโนมัติ กรุณาใช้เครื่องสแกนหรือกรอกรหัส';$('scanError').classList.remove('hidden');return}try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'}});$('video').srcObject=stream;await $('video').play();$('video').classList.remove('hidden');$('cameraIdle').classList.add('hidden');const detector=new BarcodeDetector({formats:['qr_code']});const scan=async()=>{if(!stream)return;const codes=await detector.detect($('video')).catch(()=>[]);if(codes[0]){handleScanned(codes[0].rawValue);return}requestAnimationFrame(scan)};scan()}catch{$('scanError').textContent='ไม่สามารถเปิดกล้องได้ กรุณาอนุญาตการใช้กล้องหรือกรอกรหัสแทน';$('scanError').classList.remove('hidden')}};
let scannerBuffer='',scannerAt=0;document.addEventListener('keydown',event=>{if(event.target.matches('input'))return;const now=Date.now();if(now-scannerAt>100)scannerBuffer='';scannerAt=now;if(event.key==='Enter'&&scannerBuffer.length>8){handleScanned(scannerBuffer);scannerBuffer=''}else if(event.key.length===1)scannerBuffer+=event.key});
